<?php session_start();if(!isset($_SESSION["studentsid"])){header("Location: ../index.php?msg=Please+log+in+as+Student");exit();}require_once __DIR__.'/../includes/db.php';$db=new db();$db->setconnection();$conn=$db->getConnection();$studentID=$_SESSION["studentsid"];$stmt=$conn->prepare("SELECT request_id,isbn,book_name,status FROM requests WHERE student_id=? ORDER BY request_id DESC");$stmt->bind_param("s",$studentID);$stmt->execute();$result=$stmt->get_result();?><!DOCTYPE html><html lang="en"><head><meta charset="UTF-8"><meta name="viewport" content="width=device-width,initial-scale=1.0"><title>My Requests | LMS</title><link rel="stylesheet" href="../assets/css/style.css"></head><body class="dashboard-page"><main class="wide-container"><header class="dashboard-header"><div><span class="eyebrow">Student Portal</span><h1>My Book Requests</h1><p>Track your submitted requests.</p></div><a class="logout-link" href="../logout.php">Logout</a></header><section class="request-grid"><?php if($result->num_rows>0):while($row=$result->fetch_assoc()):?><article class="request-card"><div class="request-card-top"><span class="request-id">Request #<?php echo (int)$row['request_id'];?></span><span class="status-badge"><?php echo htmlspecialchars($row['status']);?></span></div><dl class="request-details"><div><dt>ISBN</dt><dd><?php echo htmlspecialchars($row['isbn']);?></dd></div><div><dt>Book</dt><dd><?php echo htmlspecialchars($row['book_name']);?></dd></div></dl></article><?php endwhile;else:?><div class="empty-state">You have not submitted any requests yet.</div><?php endif;?></section><div class="page-actions"><a class="secondary-action" href="student_dashboard.php">← Back to Dashboard</a></div></main><?php $stmt->close();$db->closeConnection();?></body></html>